import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_PIEZA } from '../../models/museo-pieza.model.mjs';
import { MODELO_RESTAURADOR, MODELO_ASIGNACION } from '../../models/restaurador-asignacion.model.mjs';

export async function buscarPiezaRepository(piezaId) {
  const { Item } = await MODELO_PIEZA.build(EntityRepository).get(
    { piezaId },
    { consistent: true }
  );
  return Item;
}

export async function buscarRestauradorRepository(restauradorId) {
  const { Item } = await MODELO_RESTAURADOR.build(EntityRepository).get(
    { restauradorId },
    { consistent: true }
  );
  return Item;
}

export async function asignarRestauradorRepository(piezaId, restauradorId, rol) {
  const asignacion = { piezaId, restauradorId, rol };
  await MODELO_ASIGNACION.build(EntityRepository).put(
    asignacion,
    { condition: { attr: 'piezaId', exists: false } }
  );
  return asignacion;
}

import { buscarPiezaRepository, buscarRestauradorRepository, asignarRestauradorRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarRestauradorService(piezaId, restauradorId, rol) {
  const pieza = await buscarPiezaRepository(piezaId);
  const restaurador = await buscarRestauradorRepository(restauradorId);
  if (!pieza || !restaurador) {
    throw new ReferenciaInexistenteError('No existe la pieza o el restaurador');
  }
  return asignarRestauradorRepository(piezaId, restauradorId, rol);
}

import { asignarRestauradorService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const piezaId = Number(event.pathParameters.piezaId);
  const { restauradorId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarRestauradorService(piezaId, restauradorId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El restaurador ya está asignado a esa pieza' }) };
    }
    throw error;
  }
}

